[
  {
    "id": 1,
    "name": "Healthy Habits",
    "description": "Deep dive into nutrition, exercise, and personal hygiene",
    "focus": "Wellness & Life Skills"
  },
  {
    "id": 2,
    "name": "Animal Kingdom",
    "description": "Focused study of animals, habitats, and behavior",
    "focus": "Environmental & Cognitive"
  },
  {
    "id": 3,
    "name": "Math Wizards",
    "description": "Concentrated activities for arithmetic, patterns, and logic",
    "focus": "Cognitive & STEM"
  },
  {
    "id": 4,
    "name": "Story Builders",
    "description": "Writing, illustrating, and creating stories",
    "focus": "Language & Creativity"
  },
  {
    "id": 5,
    "name": "Tiny Scientists",
    "description": "Hands-on experiments exploring basic science",
    "focus": "STEM & Cognitive"
  },
  {
    "id": 6,
    "name": "Music & Movement",
    "description": "Focused rhythm, singing, and dance activities",
    "focus": "Creative & Physical"
  },
  {
    "id": 7,
    "name": "Young Gardeners",
    "description": "Plants, soil, and observation experiments",
    "focus": "Environmental & Responsibility"
  },
  {
    "id": 8,
    "name": "Tiny Engineers",
    "description": "Building, problem-solving, and STEM challenges",
    "focus": "STEM & Creativity"
  },
  {
    "id": 9,
    "name": "My Emotions",
    "description": "Explore, recognize, and express feelings",
    "focus": "Emotional & Social"
  },
  {
    "id": 10,
    "name": "Creative Artists",
    "description": "Drawing, painting, and craft projects",
    "focus": "Creativity & Fine Motor"
  },
  {
    "id": 11,
    "name": "Adventure Walks",
    "description": "Focused exploration, observation, and physical activity",
    "focus": "Physical & Environmental"
  },
  {
    "id": 12,
    "name": "Little Coders",
    "description": "Logic, sequencing, and early coding concepts",
    "focus": "STEM & Cognitive"
  },
  {
    "id": 13,
    "name": "Social Stars",
    "description": "Cooperation, teamwork, and empathy challenges",
    "focus": "Social & Emotional"
  },
  {
    "id": 14,
    "name": "Music Makers",
    "description": "Explore instruments, melody, and rhythm",
    "focus": "Creativity & Sensory"
  },
  {
    "id": 15,
    "name": "Mini Mathematicians",
    "description": "Fun number games, patterns, and puzzles",
    "focus": "Cognitive & STEM"
  },
  {
    "id": 16,
    "name": "Tiny Detectives",
    "description": "Observation, exploration, and problem-solving",
    "focus": "Cognitive & Curiosity"
  },
  {
    "id": 17,
    "name": "Life Skills Lab",
    "description": "Personal hygiene, time management, and self-care",
    "focus": "Life Skills & Wellness"
  },
  {
    "id": 18,
    "name": "Animal Care",
    "description": "Learn to care for pets, farm, and wild animals",
    "focus": "Environmental & Emotional"
  },
  {
    "id": 19,
    "name": "Story Explorers",
    "description": "Focused listening, comprehension, and narrative creation",
    "focus": "Language & Cognitive"
  },
  {
    "id": 20,
    "name": "Tiny Builders",
    "description": "Construction, design, and STEM projects",
    "focus": "STEM & Creativity"
  }
]

TASK: Select 1 theme(s) and create monthly strategy.

For HYBRID plan: Select 1 theme for deep mastery
For HOLISTIC plan: Select 2-3 themes for balanced development

Return JSON:
{
  "selected_theme_ids": [1 or 2-3 IDs],
  "monthly_agenda": {
    "primary_goal": "main goal for this month",
    "thought_process": "why these themes for this child",
    "learning_narrative": "story of this month's journey"
  },
  "weekly_progression": {
    "week_1": "Foundation & Discovery - ...",
    "week_2": "Exploration & Research - ...",
    "week_3": "Application & Practice - ...",
    "week_4": "Project & Mastery - ..."
  },
  "guidance_for_match_agent": {
    "topic_criteria": "what topics to look for",
    "skill_focus": ["skill1", "skill2", "skill3"],
    "avoid_topics": ["based on dislikes"]
  },
  "guidance_for_schedule_agent": {
    "structure_type": "hybrid_deep_dive or holistic_varied",
    "daily_balance": "how to balance activities"
  }
}

Return ONLY valid JSON, no markdown.

